// Real tests against tests/fixtures/tiny.gguf, a small file generated by
// scripts/make_tiny_gguf_fixture.py using the *reference* Python `gguf`
// library (see that script's docstring) -- so this is an independent
// oracle, not a round-trip through mini-infer's own (nonexistent) writer.
// The much larger, model-scale check (dump vs python gguf on the real
// Qwen2.5 GGUF files, and id->text decode vs HF tokenizer.decode) lives in
// scripts/compare_gguf_dump.py and scripts/compare_decode.py per
// PROMPTS.md -- those need the ~2GB model files and a Python environment,
// so they are not part of this always-run CTest suite.
#include <cmath>
#include <cstdio>
#include <cstring>

#include "gguf.h"
#include "test_util.h"

namespace {
std::string fixture_path() { return std::string(MI_FIXTURE_DIR) + "/tiny.gguf"; }

size_t find_kv_index(mi_gguf_context* ctx, const char* key) {
  for (size_t i = 0; i < mi_gguf_n_kv(ctx); i++) {
    if (std::strcmp(mi_gguf_kv_key(ctx, i), key) == 0) return i;
  }
  return (size_t)-1;
}
}  // namespace

static void test_open_missing_file() {
  std::string err;
  mi_gguf_context* ctx = mi_gguf_open("/nonexistent/path/does-not-exist.gguf", &err);
  MI_CHECK(ctx == nullptr);
  MI_CHECK(!err.empty());
}

static void test_open_bad_magic() {
  std::string bad_path = fixture_path() + ".bad";
  std::FILE* f = std::fopen(bad_path.c_str(), "wb");
  MI_CHECK(f != nullptr);
  if (f) {
    const char junk[8] = {'X', 'X', 'X', 'X', 0, 0, 0, 0};
    std::fwrite(junk, 1, sizeof(junk), f);
    std::fclose(f);
  }
  std::string err;
  mi_gguf_context* ctx = mi_gguf_open(bad_path.c_str(), &err);
  MI_CHECK(ctx == nullptr);
  MI_CHECK(!err.empty());
  std::remove(bad_path.c_str());
}

static void test_header_and_alignment(mi_gguf_context* ctx) {
  MI_CHECK(mi_gguf_version(ctx) == 3);
  // The fixture sets a non-default alignment specifically to exercise this
  // path; the real Qwen2 GGUF files never set general.alignment, so
  // without this fixture the default-32 branch would be all we ever test.
  MI_CHECK(mi_gguf_alignment(ctx) == 16);
}

static void test_scalar_kv(mi_gguf_context* ctx) {
  uint32_t u32;
  MI_CHECK(mi_gguf_get_u32(ctx, "test.u32", &u32) && u32 == 4000000000u);
  MI_CHECK(!mi_gguf_get_u32(ctx, "test.i32", &u32));  // wrong type
  MI_CHECK(!mi_gguf_get_u32(ctx, "test.does_not_exist", &u32));

  int32_t i32;
  MI_CHECK(mi_gguf_get_i32(ctx, "test.i32", &i32) && i32 == -2000000000);

  float f32;
  MI_CHECK(mi_gguf_get_f32(ctx, "test.f32", &f32) && std::fabs(f32 - 3.14f) < 1e-3f);

  bool b;
  MI_CHECK(mi_gguf_get_bool(ctx, "test.bool_true", &b) && b == true);
  MI_CHECK(mi_gguf_get_bool(ctx, "test.bool_false", &b) && b == false);

  std::string s;
  MI_CHECK(mi_gguf_get_str(ctx, "test.string", &s) &&
            s == "hello \"world\"\nwith newline and \ttab");

  // Types with no dedicated by-key getter (u8/i8/u16/i16/u64/i64/f64) are
  // still reachable generically, exactly as tools/dump uses them.
  size_t idx = find_kv_index(ctx, "test.u64");
  MI_CHECK(idx != (size_t)-1);
  if (idx != (size_t)-1) {
    MI_CHECK(mi_gguf_kv_type(ctx, idx) == MI_GGUF_TYPE_UINT64);
    std::string val;
    MI_CHECK(mi_gguf_kv_scalar_to_string(ctx, idx, &val) && val == "123456789012345");
  }

  idx = find_kv_index(ctx, "test.f64");
  MI_CHECK(idx != (size_t)-1);
  if (idx != (size_t)-1) {
    std::string val;
    MI_CHECK(mi_gguf_kv_scalar_to_string(ctx, idx, &val));
    MI_CHECK(std::fabs(std::atof(val.c_str()) - 2.718281828459045) < 1e-12);
  }
}

static void test_array_kv(mi_gguf_context* ctx) {
  size_t n = 0;
  MI_CHECK(mi_gguf_get_arr_n(ctx, "test.arr_str", &n) && n == 3);
  std::string s0, s1, s2;
  MI_CHECK(mi_gguf_get_arr_str(ctx, "test.arr_str", 0, &s0) && s0 == "a");
  MI_CHECK(mi_gguf_get_arr_str(ctx, "test.arr_str", 1, &s1) && s1 == "bb");
  MI_CHECK(mi_gguf_get_arr_str(ctx, "test.arr_str", 2, &s2) && s2 == "ccc");
  MI_CHECK(!mi_gguf_get_arr_str(ctx, "test.arr_str", 3, &s0));  // out of range

  MI_CHECK(mi_gguf_get_arr_n(ctx, "test.arr_i32", &n) && n == 4);
  int32_t v;
  MI_CHECK(mi_gguf_get_arr_i32(ctx, "test.arr_i32", 0, &v) && v == 1);
  MI_CHECK(mi_gguf_get_arr_i32(ctx, "test.arr_i32", 1, &v) && v == -2);
  MI_CHECK(mi_gguf_get_arr_i32(ctx, "test.arr_i32", 3, &v) && v == -4);

  size_t arr_f32_idx = find_kv_index(ctx, "test.arr_f32");
  MI_CHECK(arr_f32_idx != (size_t)-1);
  MI_CHECK(mi_gguf_kv_arr_type(ctx, arr_f32_idx) == MI_GGUF_TYPE_FLOAT32);
}

static void test_tensors(mi_gguf_context* ctx) {
  MI_CHECK(mi_gguf_n_tensors(ctx) == 4);

  const mi_gguf_tensor_info* t = mi_gguf_find_tensor(ctx, "t_f32");
  MI_CHECK(t != nullptr);
  if (t) {
    MI_CHECK(t->type == MI_TYPE_F32);
    MI_CHECK(t->n_dims == 1);
    MI_CHECK(t->ne[0] == 4);
    MI_CHECK(t->nbytes == 16);
    const float* data = (const float*)t->data;
    MI_CHECK(data[0] == 1.0f && data[1] == 2.0f && data[2] == 3.0f && data[3] == 4.0f);
  }

  // ne[0] must be the innermost/fastest-varying dim (SPEC.md), so a
  // [2, 3]-shaped tensor filled with arange(6).reshape(3,2) row-major reads
  // back as ne0=2 (columns), ne1=3 (rows), with element i + j*ne0 == the
  // row-major value at [j, i].
  t = mi_gguf_find_tensor(ctx, "t_f32_2d");
  MI_CHECK(t != nullptr);
  if (t) {
    MI_CHECK(t->n_dims == 2);
    MI_CHECK(t->ne[0] == 2 && t->ne[1] == 3);
    MI_CHECK(t->nbytes == 24);
    const float* data = (const float*)t->data;
    for (int j = 0; j < 3; j++) {
      for (int i = 0; i < 2; i++) {
        MI_CHECK(data[i + j * 2] == (float)(i + j * 2));
      }
    }
  }

  t = mi_gguf_find_tensor(ctx, "t_f16");
  MI_CHECK(t != nullptr);
  if (t) {
    MI_CHECK(t->type == MI_TYPE_F16);
    MI_CHECK(t->nbytes == 8);  // 4 * 2 bytes
  }

  t = mi_gguf_find_tensor(ctx, "t_q8_0");
  MI_CHECK(t != nullptr);
  if (t) {
    MI_CHECK(t->type == MI_TYPE_Q8_0);
    MI_CHECK(t->ne[0] == 32);
    MI_CHECK(t->nbytes == 34);  // one block: 2-byte scale + 32 int8
  }

  MI_CHECK(mi_gguf_find_tensor(ctx, "does_not_exist") == nullptr);
}

static void test_vocab(mi_gguf_context* ctx) {
  std::string err;
  mi_vocab* vocab = mi_vocab_load(ctx, &err);
  MI_CHECK(vocab != nullptr);
  if (!vocab) return;

  MI_CHECK(mi_vocab_size(vocab) == 2);
  // id 0: NORMAL token "ĠA" (byte-level BPE for bytes 0x20 0x41) decodes to
  // the raw bytes " A".
  MI_CHECK(mi_vocab_token_to_text(vocab, 0) == " A");
  // id 1: CONTROL token, literal text, not byte-mapped.
  MI_CHECK(mi_vocab_token_to_text(vocab, 1) == "<|test|>");

  int32_t ids[2] = {0, 1};
  MI_CHECK(mi_vocab_decode(vocab, ids, 2) == " A<|test|>");

  MI_CHECK(mi_vocab_token_to_text(vocab, 99) == "");   // out of range
  MI_CHECK(mi_vocab_token_to_text(vocab, -1) == "");   // negative

  mi_vocab_free(vocab);
}

int main() {
  test_open_missing_file();
  test_open_bad_magic();

  std::string err;
  mi_gguf_context* ctx = mi_gguf_open(fixture_path().c_str(), &err);
  MI_CHECK(ctx != nullptr);
  if (!ctx) {
    std::fprintf(stderr, "failed to open fixture: %s\n", err.c_str());
    return ::mi_test::exit_code();
  }

  test_header_and_alignment(ctx);
  test_scalar_kv(ctx);
  test_array_kv(ctx);
  test_tensors(ctx);
  test_vocab(ctx);

  mi_gguf_close(ctx);
  return ::mi_test::exit_code();
}
